{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Oritavancin, the highest-transfer direct CNS measurement, showed only 5% CSF/plasma penetration in a rabbit meningitis model, indicating poor CNS access even with inflamed meninges.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Mithramycin, a glycosylated polycyclic aromatic natural product, achieved a peak CSF:plasma ratio of only 0.12 in monkeys with little material found in normal brains, supporting poor CNS penetration for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin, a glycosylated polycyclic natural product, showed a very low CSF/plasma ratio of 0.01-0.03 in dogs, demonstrating that such glycosides do not readily cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Orientin, a highly polar glycoside, showed low brain levels after intravenous administration in rats due to difficulty crossing the blood-brain barrier, consistent with the query's very high polarity and hydrogen-bonding capacity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "SC-4453, a cardiac glycoside, had the lowest brain concentration among tissues at steady state in guinea pigs, demonstrating effective blood-brain barrier exclusion of large glycosylated natural products.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, highly polar, glycosylated anthracycline-like molecule with multiple hydrogen-bond donors/acceptors and an ionizable amino sugar. Transferable experimental evidence from glycosylated and polycyclic natural products consistently shows very low CSF/brain penetration, and the physicochemical prior predicts negligible passive BBB permeability. Therefore, meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct doxorubicin/query-specific brain or CSF pharmacokinetic record was included; conclusions rely on structurally and physicochemically related glycosylated natural products.",
    "The contribution of active efflux transporters to the query's brain exposure was not directly measured.",
    "Some records were obtained in meningitis or inflamed models, which may overestimate penetration relative to an intact blood-brain barrier."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

